pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Choose a caddress that is a simple account with no code
        address noCode = address(0x1234);
        address from = address(0x5678);
        address[] memory tos = new address[](1);
        tos[0] = address(0x9abc);
        uint v = 100;

        // The call to transfer will attempt to call transferFrom on noCode, which reverts silently (no fallback)
        // In the reference version (require inside loop), the transaction reverts.
        // In the buggy version, it does not revert and returns true.
        // We capture the revert status via try/catch:
        bool ok;
        try c.transfer(from, noCode, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference reverts, so ok is false. The buggy returns true, so ok is true.
        // We assert that ok is false, which is true for the reference but false for the buggy.
        assertTrue(ok == false, "Expected revert on failed inner call");
    }
}

